:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#121528;
  --ink:#e9ecff;
  --muted:#b7bddb;
  --faint:#8f97bf;
  --line:#2a2f52;
  --acc:#8be9fd;
  --acc2:#ffd479;
  --bad:#ff6b81;
  --good:#7CFFB2;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--ink);
  background:linear-gradient(180deg, #0b0d18, var(--bg));
  padding:18px;
  border:1px solid var(--line);
  border-radius:14px;
  max-width:980px;
  margin:0 auto;
}

.hdr{display:flex; gap:14px; align-items:flex-start; justify-content:space-between; margin-bottom:12px;}

h1{font-size:18px; margin:0 0 6px 0; letter-spacing:.2px}
h2{font-size:15px; margin:0 0 6px 0; color:var(--acc)}

.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{
  background:linear-gradient(180deg, var(--panel), var(--panel2));
  border:1px solid var(--line);
  border-radius:12px;
  padding:12px;
  margin:10px 0;
}

.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap;}
.row.small{margin-top:8px}

label{font-size:12px; color:var(--muted); min-width:64px}

input[type="text"]{
  flex:1;
  min-width:240px;
  padding:10px 10px;
  border-radius:10px;
  border:1px solid var(--line);
  background:#0b0e1c;
  color:var(--ink);
  font-family:var(--mono);
  font-size:15px;
  outline:none;
}
input[type="text"]:focus{border-color:#3b4278; box-shadow:0 0 0 3px rgba(139,233,253,.08)}

button{
  padding:10px 12px;
  border-radius:10px;
  border:1px solid #3b4278;
  background:#1b2150;
  color:var(--ink);
  cursor:pointer;
  font-weight:600;
}
button:hover{filter:brightness(1.08)}
button:active{transform:translateY(1px)}
button.ghost{background:transparent; border-color:var(--line); color:var(--muted)}

.tog{display:flex; gap:8px; align-items:center; color:var(--muted); font-size:12px}
.tog input{transform:translateY(1px)}

.out{display:grid; grid-template-columns:1fr 1fr 1.2fr; gap:10px; margin-top:12px}
@media (max-width:820px){.out{grid-template-columns:1fr}}

.card{
  border:1px solid var(--line);
  border-radius:12px;
  padding:10px;
  background:rgba(0,0,0,.18);
}
.k{font-size:11px; color:var(--faint); margin-bottom:6px; text-transform:uppercase; letter-spacing:.08em}
.v{font-family:var(--mono); font-size:14px; line-height:1.25}
.v.big{font-size:20px}

.help{margin-top:10px; border:1px dashed var(--line); border-radius:12px; padding:8px 10px; color:var(--muted)}
.help summary{cursor:pointer; color:var(--acc2); font-weight:700}
.helpin{margin-top:8px; font-size:13px; line-height:1.35}
.helpin ul{margin:8px 0 0 18px; padding:0}
.helpin li{margin:4px 0}

.ft{margin-top:10px; display:flex; flex-direction:column; gap:8px}
.fine{margin:0; color:var(--faint); font-size:12px}

.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{
  font-family:var(--mono);
  font-size:13px;
  padding:6px 10px;
  border-radius:999px;
  border:1px solid var(--line);
  background:rgba(255,255,255,.03);
  color:var(--ink);
  cursor:pointer;
}
.chip:hover{border-color:#3b4278}

.badge{display:inline-block; padding:2px 8px; border-radius:999px; font-size:11px; border:1px solid var(--line); margin-left:6px; color:var(--muted)}

.noteGood{color:var(--good)}
.noteBad{color:var(--bad)}
body{margin:0}.wrap{overflow-wrap:anywhere}.card{min-width:0}input[type="text"]{min-width:0;flex-basis:240px;max-width:100%}.row{min-width:0}

